import { isMediaHostUrl } from '@/api/profiles/profile-picture-url';

// IPFS gateway URLs generated by the app for pinned media.
const IPFS_GATEWAY_ORIGIN = 'https://media.6529.io';
const IPFS_GATEWAY_PREFIX = `${IPFS_GATEWAY_ORIGIN}/ipfs/`;

function isIpfsGatewayUrl(value: string): boolean {
  if (
    !value.startsWith(IPFS_GATEWAY_PREFIX) ||
    value.length === IPFS_GATEWAY_PREFIX.length ||
    /\s/.test(value)
  ) {
    return false;
  }
  try {
    const url = new URL(value);
    return (
      url.origin === IPFS_GATEWAY_ORIGIN &&
      url.port === '' &&
      url.username === '' &&
      url.password === '' &&
      url.pathname.startsWith('/ipfs/')
    );
  } catch {
    return false;
  }
}

/**
 * Push notification images are fetched by the receiving device, so only
 * images served from our own media hosts are attached: the media CDN (same
 * exact check as new profile pictures) or the IPFS gateway under /ipfs/.
 */
export function isAllowedPushNotificationImageUrl(
  url: string | null | undefined
): url is string {
  if (typeof url !== 'string') {
    return false;
  }
  const value = url.trim();
  return value !== '' && (isMediaHostUrl(value) || isIpfsGatewayUrl(value));
}
